--- a/invoice/coupons.py
+++ b/invoice/coupons.py
@@ -8,7 +8,7 @@ def coupon_value(code: str, amount: float) -> float:
     try:
         kind, value = COUPONS[code.upper()]
     except KeyError:
         raise ValueError(f"unknown coupon {code!r}") from None
     if kind == "percent":
         return round(amount * value / 100, 2)
-    return value
+    return min(value, amount)

